DROP TABLE IF EXISTS CLIENTE;
  
CREATE TABLE CLIENTE
(nro_cliente INTEGER NOT NULL,
 run TEXT(45) NOT NULL,
 pnombre TEXT(50) NULL, 
 apellidos TEXT(100) NULL,
 fecha_nacimiento TEXT(20) NOT NULL,
 fecha_inscripcion TEXT(20) NOT NULL,
 correo TEXT(20),
 direccion TEXT(50) NOT NULL,
 cod_prof_ofic  INTEGER NOT NULL,
 cod_tipo_cliente  INTEGER NOT NULL,
 CONSTRAINT PK_CLIENTE PRIMARY KEY(nro_cliente)); 

